# document_models.py\n# [HELPER] Defines local request, response, and normalization helpers for Structured Document Extraction\n\nfrom __future__ import annotations\nfrom dataclasses import dataclass, field\nfrom typing import List, Optional\n\n@dataclass\nclass InvoiceExtractionRequest:\n    file_path: str\n    document_type: str = 'invoice'\n\n@dataclass\nclass InvoiceExtractionResponse:\n    vendor: str = ''\n    date: str = ''\n    total: float = 0.0\n    line_items: List[str] = field(default_factory=list)\n    confidence: float = 0.0\n\n@dataclass\nclass ReceiptExtractionRequest:\n    file_path: str\n    document_type: str = 'receipt'\n\n@dataclass\nclass ReceiptExtractionResponse:\n    merchant: str = ''\n    tax: float = 0.0\n    total: float = 0.0\n    items: List[str] = field(default_factory=list)\n    confidence: float = 0.0\n\n@dataclass\nclass NormalizedExpense:\n    vendor: str = ''\n    date: Optional[str] = None\n    total: float = 0.0\n    items: List[str] = field(default_factory=list)\n\n@dataclass\nclass NormalizationResult:\n    expense: NormalizedExpense\n    success: bool\n    message: str = ''\n\n@dataclass\nclass ExtractionResult:\n    raw: dict\n    normalized: Optional[NormalizationResult] = None\n\n@dataclass\nclass ValidationResult:\n    is_valid: bool\n    details: dict\n
